// ============================================================
// 📌 قانون چیدمان دکمه‌ها — برای هر ویرایش آیندهٔ این فایل (انسان یا هوش مصنوعی):
// ۱) دکمه‌ها همیشه کنار هم در ردیف چیده شوند؛ هر دکمه در یک ردیف جدا ممنوع.
// ۲) اگر متن دکمه‌ها کوتاه است: ۳ تا ۴ دکمه در هر ردیف (با grid4/grid3/grid2).
// ۳) فقط اگر متن دکمه خیلی بلند است: آن دکمه تنها در یک ردیف باشد.
// ۴) استثنا: جفت تأییدی (بله/انصراف) دوتایی در یک ردیف می‌ماند.
// هدف: چت تمیز و جلوگیری از انباشت پیام‌های بلند.
// ============================================================
// 📞 ارتباط با سازنده — پیام مشتری به ربات سازنده فرستاده می‌شود.
// روی ورکر سازنده یک اندپوینت POST /contact هست که پیام را همراه مشخصات
// مشتری (نام ربات، ورکر، اکانت، نسخه، فرستنده) به ادمین همان ورکر می‌فرستد.
// توکن ربات سازنده هیچ‌جا داخل کد نیست؛ فقط این اندپوینت صدا زده می‌شود.
const CREATOR_CONTACT_URL = "https://cloud-guardian.yaram169.workers.dev/contact";
const CREATOR_CONTACT_KEY = "cg-creator-9f3a7c1b2e64d8a0";

// فقط مقصدهای امن (http/https و میزبان عمومی، نه IP خصوصی) برای پاسخ سازنده پذیرفته می‌شود
function safeReplyUrl(u) {
  const s = String(u || "").trim();
  if (!/^https?:\/\/[a-z0-9][a-z0-9.\-]*/i.test(s)) return "";
  let host = "";
  try {
    host = new URL(s).hostname.toLowerCase();
  } catch (e) {
    return "";
  }
  if (!host) return "";
  if (host === "localhost" || host.endsWith(".local")) return "";
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return "";
  if (/^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host)) return "";
  return s.replace(/\/+$/, "");
}
