const CF_API = "https://api.cloudflare.com/client/v4";
const LINODE_API = "https://api.linode.com/v4";
const HETZNER_API = "https://api.hetzner.cloud/v1";
// آروان: CDN/DNS نسخه ۴ + سرور ابری (ECC) نسخه ۱ — احراز هویت با کلید ماشین‌یوزر:
// Authorization: Apikey <uuid> (بدون پیشوند اضافی؛ ورودی کاربر نرمالایز می‌شود)
const ARVAN_API = "https://napi.arvancloud.ir/cdn/4.0";
const ARVAN_ECC = "https://napi.arvancloud.ir/ecc/v1";
// ریجن‌های شناخته‌شدهٔ سرور ابری آروان + امکان ورود دستی ریجن دلخواه
// (فهرست اصلی همیشه زنده از API خوانده می‌شود؛ این فقط fallback است)
const ARVAN_REGIONS = ["ir-thr-ba1", "ir-thr-fr1", "ir-tbz-sh1", "ir-thr-si1", "ir-southwest1-a", "eu-west1-a"];

// نام فارسی کشور/شهر/دیتاسنترهای آروان
const ARVAN_FA = {
  Iran: "ایران", Germany: "آلمان", Netherlands: "هلند",
  Tehran: "تهران", Tabriz: "تبریز", Ahwaz: "اهواز", Isfahan: "اصفهان", Shiraz: "شیراز", Mashhad: "مشهد", Karlsruhe: "کارلسروهه", Amsterdam: "آمستردام",
  Bamdad: "بامداد", Foroogh: "فروغ", Forough: "فروغ", Shahriar: "شهریار", Qeysar: "قیصر", Simin: "سیمین", Goethe: "گوته", Atieh: "عطیه",
};

function arvanRegionFa(r) {
  const t = (s) => ARVAN_FA[s] || s || "";
  const loc = [t(r.country), t(r.city), t(r.dc)].filter(Boolean).join(" ـ ");
  return loc || r.code || "";
}

// فهرست زندهٔ ریجن‌ها از API (فقط visible و قابل ساخت)
async function arvanGetRegions(token, kv, env) {
  try {
    const d = await arvanFetch(token, "/regions", {}, 30000, kv, env, ARVAN_ECC);
    const arr = arvanEccList(d) || [];
    const live = arr
      .filter((r) => r && r.code && r.visible !== false && r.create !== false)
      .map((r) => ({ code: r.code, fa: arvanRegionFa(r), def: !!r.default }));
    if (live.length) return live;
  } catch (e) {}
  return ARVAN_REGIONS.map((c) => ({ code: c, fa: c, def: false }));
}
const RECORD_TYPES = ["A", "AAAA", "CNAME"];
const PAGE_SIZE = 8;
const RECORD_PAGE_SIZE = 18;
const CZ_PAGE_SIZE = 12;
const CZR_PAGE_SIZE = 16;
const LN_PAGE_SIZE = 10;
const HZ_PAGE_SIZE = 10;

const EMPTY_BTN = { text: "\u00A0", callback_data: "noop" };

let _lastSelfOrigin = "";

// ============================================================
// in-isolate micro cache — برای کاهش شدید مصرف Workers KV
// مقادیر پرخواندنی (کانفیگ/اکانت/پنل/کش) در حافظهٔ ایزوله نگه داشته
// می‌شوند و روی هر write باطل/به‌روز می‌شوند. TTL کوتاه = محافظت از
// دادهٔ کهنه در صورت نوشتن توسط ایزولهٔ دیگر.
// ============================================================
const _mem = new Map();
const MEM_TTL = 60000;

function memSet(key, val, ttl = MEM_TTL) {
  if (_mem.size > 800) _mem.clear();
  _mem.set(key, { v: val, exp: Date.now() + ttl });
}

function memGet(key) {
  const e = _mem.get(key);
  if (!e) return undefined;
  if (e.exp < Date.now()) {
    _mem.delete(key);
    return undefined;
  }
  return e.v;
}

function memDel(key) {
  _mem.delete(key);
}

async function kvGetCached(kv, key, type, ttl = MEM_TTL) {
  if (!kv) return null;
  const hit = memGet("kv:" + key);
  if (hit !== undefined) return hit;
  const val = await kv.get(key, type);
  if (val !== null && val !== undefined) memSet("kv:" + key, val, ttl);
  return val;
}

async function kvPutCached(kv, key, value, opts, ttl = MEM_TTL) {
  if (!kv) return;
  await kv.put(key, value, opts);
  try {
    memSet("kv:" + key, JSON.parse(value), ttl);
  } catch {
    memSet("kv:" + key, value, ttl);
  }
}

async function kvDeleteCached(kv, key) {
  if (!kv) return;
  memDel("kv:" + key);
  await kv.delete(key);
}

function grid2(buttons) {
  const rows = [];
  for (let i = 0; i < buttons.length; i += 2) {
    const row = [buttons[i]];
    row.push(buttons[i + 1] || EMPTY_BTN);
    rows.push(row);
  }
  return rows;
}
// چیدمان ۳ و ۴ ستونه برای دکمه‌های کوتاه (طبق قانون چیدمان بالای فایل)
function grid3(buttons) {
  const rows = [];
  for (let i = 0; i < buttons.length; i += 3) {
    const row = [buttons[i]];
    row.push(buttons[i + 1] || EMPTY_BTN);
    row.push(buttons[i + 2] || EMPTY_BTN);
    rows.push(row);
  }
  return rows;
}
function grid4(buttons) {
  const rows = [];
  for (let i = 0; i < buttons.length; i += 4) {
    const row = [buttons[i]];
    row.push(buttons[i + 1] || EMPTY_BTN);
    row.push(buttons[i + 2] || EMPTY_BTN);
    row.push(buttons[i + 3] || EMPTY_BTN);
    rows.push(row);
  }
  return rows;
}

